function validate([room, row, col]) {
  const m = room.length;
  if (m < 1 || m > 100) return 'room needs 1 to 100 rows.';
  const n = room[0].length;
  if (n < 1 || n > 200) return 'Each row of room needs 1 to 200 cells.';
  if (room.some(line => line.length !== n)) return 'Every row of room must have the same length.';
  if (room.some(line => line.some(v => v !== 0 && v !== 1))) return 'Each cell is 0 (wall) or 1 (open).';
  if (!Number.isInteger(row) || row < 0 || row >= m || !Number.isInteger(col) || col < 0 || col >= n) return 'row and col must name a cell inside room.';
  if (room[row][col] !== 1) return 'The robot must start on an open cell.';
  const open = room.reduce((sum, line) => sum + line.reduce((s, v) => s + v, 0), 0);
  if (open > 1500) return 'The local judge supports rooms with up to 1,500 open cells.';
  const seen = room.map(line => line.map(() => false));
  const stack = [[row, col]];
  seen[row][col] = true;
  let reached = 1;
  while (stack.length) {
    const [r, c] = stack.pop();
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && room[nr][nc] === 1 && !seen[nr][nc]) { seen[nr][nc] = true; reached++; stack.push([nr, nc]); }
    }
  }
  if (reached !== open) return 'Every open cell must be reachable from the start.';
  return null;
}

