function adapt(input, solve, kit) {
  const [room, row, col] = input;
  const steps = [[-1, 0], [0, 1], [1, 0], [0, -1]];
  const result = room.map(line => line.slice());
  const open = room.reduce((sum, line) => sum + line.reduce((s, v) => s + v, 0), 0);
  const limit = 200 * open + 1000;
  let r = row, c = col, facing = 0, calls = 0;
  const count = () => {
    calls++;
    if (calls > limit) throw new Error('The robot made too many API calls; make sure every cell is entered only once.');
  };
  // The robot is the only window into the room; its position and facing stay hidden in this closure.
  const robot = Object.freeze({
    move() {
      count();
      const nr = r + steps[facing][0], nc = c + steps[facing][1];
      if (nr < 0 || nr >= room.length || nc < 0 || nc >= room[0].length || room[nr][nc] === 0) return false;
      r = nr;
      c = nc;
      return true;
    },
    turnLeft() { count(); facing = (facing + 3) % 4; },
    turnRight() { count(); facing = (facing + 1) % 4; },
    clean() { count(); result[r][c] = 2; }
  });
  solve(robot);
  return result;
}

