function cleanRoom(robot) {
  const directions = [[-1, 0], [0, 1], [1, 0], [0, -1]];
  const visited = new Set();

  function goBack() {
    robot.turnRight();
    robot.turnRight();
    robot.move();
    robot.turnRight();
    robot.turnRight();
  }

  function backtrack(row, col, facing) {
    visited.add(`${row},${col}`);
    robot.clean();
    for (let turn = 0; turn < 4; turn++) {
      const dir = (facing + turn) % 4;
      const nextRow = row + directions[dir][0];
      const nextCol = col + directions[dir][1];
      if (!visited.has(`${nextRow},${nextCol}`) && robot.move()) {
        backtrack(nextRow, nextCol, dir);
        goBack();
      }
      robot.turnRight();
    }
  }

  backtrack(0, 0, 0);
}

