function cleanRoom(robot) {
  // Absolute headings (0 up, 1 right, 2 down, 3 left), an explicit path stack, and a map of every cell tried.
  const dr = [-1, 0, 1, 0], dc = [0, 1, 0, -1];
  const known = new Map([['0,0', 'open']]);
  const path = [];
  let r = 0, c = 0, heading = 0;
  const face = d => { while (heading !== d) { robot.turnLeft(); heading = (heading + 3) % 4; } };
  robot.clean();
  for (;;) {
    let advanced = false;
    for (let d = 3; d >= 0 && !advanced; d--) {
      const key = (r + dr[d]) + ',' + (c + dc[d]);
      if (known.has(key)) continue;
      face(d);
      if (robot.move()) {
        known.set(key, 'open');
        r += dr[d];
        c += dc[d];
        path.push(d);
        robot.clean();
        advanced = true;
      } else known.set(key, 'wall');
    }
    if (advanced) continue;
    if (!path.length) return;
    const back = (path.pop() + 2) % 4;
    face(back);
    robot.move();
    r += dr[back];
    c += dc[back];
  }
}

