function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 100 : 1 + pick(5);
  const n = size === 'large' ? 100 : 1 + pick(6);
  const wallRate = [0, 0.15, 0.3, 0.4][pick(4)];
  const room = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < wallRate ? 0 : 1)));
  const row = pick(m), col = pick(n);
  room[row][col] = 1;
  // Keep only open cells reachable from the start, as the problem guarantees, and at most 1,500 of them:
  // a prefix of the breadth-first order is always connected.
  const cap = 1500;
  const reach = room.map(line => line.map(() => false));
  const order = [[row, col]];
  reach[row][col] = true;
  for (let i = 0; i < order.length; i++) {
    const [r, c] = order[i];
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nr = r + dr, nc = c + dc;
      if (order.length < cap && nr >= 0 && nr < m && nc >= 0 && nc < n && room[nr][nc] === 1 && !reach[nr][nc]) { reach[nr][nc] = true; order.push([nr, nc]); }
    }
  }
  return [room.map((line, r) => line.map((v, c) => (reach[r][c] ? 1 : 0))), row, col];
}
